 func (hs *HEARTService) handleEntropySpike(entropy, threshold float64) {
 	log.Printf("HEART entropy spike: %.4f > %.4f, routing to gap queue", entropy, threshold)
 	hs.mu.Lock()
 	if hs.stats.HeuristicUsage == nil {
